fix:
Generate arrivals on an independent timeline (open-loop), sleep until absolute deadlines, bound in-flight requests, and measure each request from its intended start time so queueing behind a stall (including waiting for an in-flight permit) is counted.
```rust
let permits = Arc::new(Semaphore::new(max_in_flight));
let mut intended = Instant::now();
loop {
    intended += arrivals.next_gap(); // absolute schedule, independent of responses
    if let Some(wait) = intended.checked_duration_since(Instant::now()) {
        tokio::time::sleep(wait).await;
    }
    let permit = permits.clone().acquire_owned().await?;
    let (client, hist) = (client.clone(), hist.clone());
    tokio::spawn(async move {
        let _ = client.send_request().await;
        hist.record(intended.elapsed().as_nanos() as u64); // from intended start
        drop(permit);
    });
}
```
